نقش سازمانی: retail_buying_manager (retail_buying_manager)

درخواست کاربر:
تجزیهٔ رشد هزینهٔ «میوه و سبزیجات» به قیمت و حجم. (فروشگاه‌های زنجیره‌ای رفاه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارش خرید به تفکیک تأمین‌کننده و دسته",
      "dimensions": [
        "supplier",
        "category",
        "month"
      ],
      "measures": [
        "amount_m",
        "qty_ton",
        "unit_price_k"
      ]
    },
    {
      "dataset": "price_index",
      "description": "شاخص قیمت خرید هر دسته",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "index"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "price_variance",
      "description": "اختلاف قیمت خرید از شاخص بازار",
      "formula": "قیمت خرید منهای شاخص",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "خرید مرکزی برای ۱۲۰ شعبه با مرکز توزیع واحد",
    "هدف پیشروی کالا ۸۵٪ تا پایان دوره",
    "پیمانهٔ سالانه با تأمین‌کنندگان کلیدی و بازنگری فصلی"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "price_variance"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "category": "میوه و سبزیجات",
  "unit_price_k": {
    "prev": 48.7,
    "curr": 61.9,
    "change_pct": 27.1
  },
  "qty_ton": {
    "prev": 700,
    "curr": 510
  },
  "amount_m": {
    "prev": 34090,
    "curr": 31569
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "price_index",
    "filters": {
      "category": "میوه و سبزیجات",
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "market_index_change_pct": 27.1,
  "note": "شاخص بازار هم‌جهت با قیمت خرید ما حرکت کرده"
}

نقش سازمانی: retail_buying_manager (retail_buying_manager)

درخواست کاربر:
جابجایی تأمین «لوازم مصرفی» به عرضه‌کنندهٔ جدید را ارزیابی کن. (مدیر خرید — هایپرمی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_scorecard",
      "description": "عملکرد تأمین‌کنندگان",
      "dimensions": [
        "supplier",
        "month"
      ],
      "measures": [
        "on_time_rate",
        "rejection_rate",
        "fill_rate"
      ]
    },
    {
      "dataset": "price_index",
      "description": "شاخص قیمت خرید هر دسته",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "index"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "price_variance",
      "description": "اختلاف قیمت خرید از شاخص بازار",
      "formula": "قیمت خرید منهای شاخص",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "ارزیابی ماهانهٔ تحویل به‌موقع و مرجوعی تأمین‌کنندگان",
    "هدف پیشروی کالا ۸۵٪ تا پایان دوره",
    "پیمانهٔ سالانه با تأمین‌کنندگان کلیدی و بازنگری فصلی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_scorecard",
    "filters": {
      "supplier": "تأمین‌کنندهٔ جدید",
      "period": "na"
    }
  }
}

TOOL_OBSERVATION:
{
  "status": "سابقهٔ عملکردی موجود نیست",
  "missing": [
    "شرایط مرجوعی و جریمهٔ تأخیر",
    "پایداری قیمت در طول پیمانه",
    "ظرفیت زنجیرهٔ سرد در پیک تابستان",
    "مشتریان مرجع و سابقهٔ تحویل"
  ]
}

TOOL_CALL:
